import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[{"level":1,"title":"简介","slug":"简介"},{"level":2,"title":"原型定义","slug":"原型定义"}],"relativePath":"api/SIMD-API/基础API/同步控制/核内同步/Mutex（ISASI）/简介.md","filePath":"api/SIMD-API/基础API/同步控制/核内同步/Mutex（ISASI）/简介.md"}'),l={name:"api/SIMD-API/基础API/同步控制/核内同步/Mutex（ISASI）/简介.md"};function i(p,e,c,o,u,r){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p>Mutex用于核内异步流水指令之间的同步处理，其功能类似于传统CPU中的锁机制。通过锁定指定流水再释放流水来完成流水间的同步依赖。每个锁有固定的一个MutexID，该ID可通过用户自定义（范围为0-27）或者通过<a href="./../AllocMutexID-(ISASI).html">AllocMutexID/ReleaseMutexID</a>进行申请释放。当用户进行自定义配置时，接口性能达到最优，但此时无法与<a href="./../../../资源管理/Pipe和Que框架/TQue/TQue.html">TQue</a>等接口配合使用，若通过<a href="./../AllocMutexID-(ISASI).html">AllocMutexID/ReleaseMutexID</a>申请释放，则可与TQue等框架接口混合使用。</p><ul><li>Lock：根据MutexID获取Mutex，并阻塞当前流水指令队列，直到对应的MutexID被Unlock。</li><li>Unlock：直到前置当前流水指令退出后，根据MutexID释放对应Mutex。</li></ul><h2 id="原型定义" tabindex="-1">原型定义 <a class="header-anchor" href="#原型定义" aria-label="Permalink to &quot;原型定义&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using MutexID = uint8_t;</span></span>
<span class="line"><span>class Mutex {</span></span>
<span class="line"><span>template &lt;pipe_t pipe&gt;</span></span>
<span class="line"><span>static __aicore__ inline void Lock(MutexID id);</span></span>
<span class="line"><span>template &lt;pipe_t pipe&gt;</span></span>
<span class="line"><span>static __aicore__ inline void Unlock(MutexID id);</span></span>
<span class="line"><span>};</span></span></code></pre></div>`,5)])])}const d=a(l,[["render",i]]);export{_ as __pageData,d as default};
